import type { ElegantConstRoute, ElegantRoute } from '@elegant-router/types';
import { generatedRoutes } from '../elegant/routes';
import { layouts, views } from '../elegant/imports';
import { transformElegantRoutesToVueRoutes } from '../elegant/transform';

/**
 * Constant routes generated by elegant-router (login / error pages / iframe).
 *
 * Business pages are not part of this list: they are registered at runtime from the backend permission tree.
 */
export function createConstantRoutes(): ElegantRoute[] {
  return generatedRoutes.filter(route => route.meta?.constant);
}

/**
 * Get auth vue routes
 *
 * @param routes Elegant routes
 */
export function getAuthVueRoutes(routes: ElegantConstRoute[]) {
  return transformElegantRoutesToVueRoutes(routes, layouts as any, views as any);
}
